namespace ghidra.app.decompiler;



using ghidra.framework;
using ghidra.util;

/**
 * Factory that returns a DecompileProcess.
 */
public class DecompileProcessFactory {

	private static string exepath;
	private static readonly string EXECNAME = "decompile";
	private static readonly string WIN32_EXECNAME = "decompile.exe";

	private static bool errorDisplayed = false;
	
	private static bool getAndSetErrorDisplayed() {
		bool b = errorDisplayed;
		if (!b) {
			errorDisplayed = true;
		}
		return b;
	}

	public static DecompileProcess get() {
		getExePath();
		DecompileProcess currentProcess = new DecompileProcess(exepath);
		return currentProcess;
	}

	public static void release(DecompileProcess dp) {
		dp.dispose();
	}

	private static void getExePath() {
		if (exepath != null) {
			return;
		}

		string exeName;
		if (Platform.CURRENT_PLATFORM.getOperatingSystem() == OperatingSystem.WINDOWS) {
			exeName = WIN32_EXECNAME;
		}
		else {
			exeName = EXECNAME;
		}

		try {
			File file = Application.getOSFile(exeName);
			exepath = file.getAbsolutePath();
		}
		catch (OSFileNotFoundException e) {
			if (!getAndSetErrorDisplayed()) {
				Msg.showError(typeof(DecompileProcessFactory), null, "Decompiler Not Found",
					e.getMessage());
			}
		}
	}
}
